/* @lc app=leetcode id=3826 lang=kotlin */ class Solution { fun cost(P: LongArray, a: Int, b: Int): Long = (P[b] - P[a]).let { it * (it + 1) / 2 } fun dc(prev: LongArray, cur: LongArray, P: LongArray, lo: Int, hi: Int, ol: Int, oh: Int): Unit = if (lo > hi) Unit else ((lo + hi) / 2).let { mid -> (ol..minOf(oh, mid - 1)).minByOrNull { prev[it] + cost(P, it, mid) }!!.let { best -> cur.set(mid, prev[best] + cost(P, best, mid)).also { dc(prev, cur, P, lo, mid - 1, ol, best) }.also { dc(prev, cur, P, mid + 1, hi, best, oh) } } } fun minPartitionScore(nums: IntArray, k: Int): Long = nums.runningFold(0L) { a, b -> a + b }.toLongArray().let { P -> (1..k).fold(LongArray(nums.size + 1) { if (it == 0) 0L else 1_000_000_000_000_000_000L }) { prev, j -> LongArray(nums.size + 1) { 1_000_000_000_000_000_000L }.also { cur -> dc(prev, cur, P, j, nums.size, j - 1, nums.size - 1) } }[nums.size] } }